#!/usr/bin/env bash
# Fully generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
#
# Self-test for tests/check_integration_ref.sh. The check is informational, so
# what matters is which line it prints: 0 is not enough to tell the four states
# apart. Each case builds a throwaway checkout and asserts the rc together with
# the wording, so a rename of the OK/WARN forms is caught here rather than in a
# transcript that reads the number as a verdict.
#
# Exit codes: 0 all cases pass, 1 a case mismatched, 2 setup failed.
set -u

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
GATE="$ROOT/tests/check_integration_ref.sh"
[ -f "$GATE" ] || { echo "self-test: gate not found at $GATE" >&2; exit 2; }

if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -w "$USERPROFILE/AppData/Local/Temp")
else
    tmpbase="${TMPDIR:-/tmp}"
fi
SANDBOX="$(mktemp -d "$tmpbase/pime-integration-ref-selftest.XXXXXX")" || {
    echo "self-test: no sandbox" >&2; exit 2; }
trap 'rm -rf "$SANDBOX"' EXIT

failures=0
out=''
rc=0
# The gate runs outside a command substitution so the shared out/rc pair survives:
# inside one, only the number comes back.
run_gate() { # dir
    out=$( cd "$1" && bash "$GATE" 2>&1 )
    rc=$?
}
check() { # name want
    if [ "$2" = "$rc" ]; then
        printf 'ok    %s (rc %s)\n' "$1" "$rc"
    else
        printf 'FAIL  %s: want rc %s, got rc %s | %s\n' "$1" "$2" "$rc" "$out"
        failures=$((failures + 1))
    fi
}
expect() { # name needle
    if printf '%s\n' "$out" | grep -qF -e "$2"; then
        printf 'ok    %s\n' "$1"
    else
        printf 'FAIL  %s: no line holding %s | %s\n' "$1" "$2" "$out"
        failures=$((failures + 1))
    fi
}

new_repo() { # name — master carrying the harness
    local dir="$SANDBOX/$1"
    mkdir -p "$dir/docs/agents" || return 1
    ( cd "$dir" && git init -q . && printf '# glossary\n' > GLOSSARY.md \
        && printf '# agents\n' > docs/agents/verification.md \
        && git add -A && git -c user.email=a@b -c user.name=a commit -qm t ) >/dev/null 2>&1 || return 1
    printf '%s' "$dir"
}

# 1. Only `master` holds the harness: it is excluded from the candidate set.
d=$(new_repo masteronly) || { echo "self-test: sandbox init failed" >&2; exit 2; }
run_gate "$d"
check "master alone is not a carrier" 0
expect "no record branch named" 'no local record branch carries the harness'

# 2. One record branch, not the checked-out one.
( cd "$d" && git branch local/stroke-parked ) >/dev/null 2>&1
run_gate "$d"
check "one carrier" 0
expect "names the carrier" 'integration ref: local/stroke-parked'
expect "marks it not checked out" 'not checked out'

# 3. The same branch checked out.
( cd "$d" && git checkout -q local/stroke-parked ) >/dev/null 2>&1
run_gate "$d"
check "the carrier is checked out" 0
expect "marks it checked out" '(checked out)'

# 4. Two carriers: the ambiguity the check exists to print.
( cd "$d" && git branch local/linux-master ) >/dev/null 2>&1
run_gate "$d"
check "two carriers" 0
expect "warns about the count" 'local record branches carry the harness'
expect "arrow marks the checked-out ref" '-> '

# 5. A checkout with no committed tree at all.
d2="$SANDBOX/empty"; mkdir -p "$d2"
( cd "$d2" && git init -q . ) >/dev/null 2>&1
run_gate "$d2"
check "empty repo" 0
expect "no carrier reported" 'no local record branch carries the harness'

# 6. Outside a repository: not applicable.
run_gate "$SANDBOX"
check "outside a repo" 125

if [ "$failures" -ne 0 ]; then
    printf 'Self-test failed (%d case(s))\n' "$failures" >&2
    exit 1
fi
echo "Self-test passed"
